SET NAMES utf8mb4;
CREATE TABLE organizations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL,short_name VARCHAR(20),type ENUM('department','standalone') NOT NULL DEFAULT 'standalone',country VARCHAR(80),city VARCHAR(80),state VARCHAR(80),contact_email VARCHAR(120),contact_phone VARCHAR(20),active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE blood_centers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,org_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(10) NOT NULL,country VARCHAR(80),state VARCHAR(80),city VARCHAR(80),location_detail VARCHAR(200),phenotyping_capable TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_code_org(code,org_id),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE staff(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,role ENUM('super_admin','dept_admin','center_incharge','doctor','technician','nurse') NOT NULL DEFAULT 'technician',org_id INT UNSIGNED,center_id INT UNSIGNED,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(center_id) REFERENCES blood_centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,key_name VARCHAR(60) NOT NULL UNIQUE,value TEXT,description VARCHAR(200),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE blood_groups(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(4) NOT NULL UNIQUE,abo CHAR(2) NOT NULL,rh VARCHAR(4) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE antigen_systems(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,system_name VARCHAR(20) NOT NULL,antigens VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE known_antibodies(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL UNIQUE,`system` VARCHAR(20) NOT NULL,clinical_significance ENUM('High','Moderate','Low','Unknown') NOT NULL DEFAULT 'High') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE patients(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL UNIQUE,hid VARCHAR(30),aadhaar_hash CHAR(64) NOT NULL UNIQUE,aadhaar_last4 CHAR(4) NOT NULL,full_name VARCHAR(160) NOT NULL,guardian_name VARCHAR(160),sex ENUM('Male','Female','Other'),dob DATE,mobile VARCHAR(15),address TEXT,blood_group VARCHAR(4),diagnosis ENUM('Thal Major','Thal Intermedia','HbE-Beta','Sickle','Other') NOT NULL,pin_hash VARCHAR(255) NOT NULL,org_id INT UNSIGNED NOT NULL,registered_by INT UNSIGNED,registered_center_id INT UNSIGNED,registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,active TINYINT(1) NOT NULL DEFAULT 1,notes TEXT,UNIQUE KEY uq_patients_hid(hid),INDEX idx_patient_aadhaar(aadhaar_hash),INDEX idx_patient_mobile(mobile),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(registered_by) REFERENCES staff(id),CONSTRAINT fk_patients_registered_center FOREIGN KEY(registered_center_id) REFERENCES blood_centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE blood_groupings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL,center_id INT UNSIGNED NOT NULL,method ENUM('slide','tube','gel','automated') NOT NULL,anti_A VARCHAR(3),anti_B VARCHAR(3),anti_AB VARCHAR(3),anti_D_IgM VARCHAR(3),anti_D_IgG VARCHAR(3),anti_A1 VARCHAR(3),anti_H VARCHAR(3),rh_control VARCHAR(3),cell_A1 VARCHAR(3),cell_A2 VARCHAR(3),cell_B VARCHAR(3),cell_O VARCHAR(3),forward_group VARCHAR(4),reverse_group VARCHAR(4),concordant TINYINT(1),discordance_note TEXT,weak_D_tested TINYINT(1),weak_D_result VARCHAR(20),final_abo_rh VARCHAR(4),recent_transfusion_3mo TINYINT(1),performed_by INT UNSIGNED,performed_date DATE NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(center_id) REFERENCES blood_centers(id),FOREIGN KEY(performed_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE phenotypes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL UNIQUE,antigen_C TINYINT(1),antigen_c_lower TINYINT(1),antigen_E TINYINT(1),antigen_e_lower TINYINT(1),antigen_Jka TINYINT(1),antigen_Jkb TINYINT(1),antigen_Fya TINYINT(1),antigen_Fyb TINYINT(1),antigen_M TINYINT(1),antigen_N TINYINT(1),antigen_S TINYINT(1),antigen_s_lower TINYINT(1),phenotype_string VARCHAR(100),typed_by INT UNSIGNED,typed_at DATETIME,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(typed_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE serology_workups(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL,center_id INT UNSIGNED NOT NULL,dct_done TINYINT(1),dct_result VARCHAR(20),dct_grade VARCHAR(3),ict_done TINYINT(1),ict_result VARCHAR(20),ict_grade VARCHAR(3),three_cell_done TINYINT(1),three_cell_result VARCHAR(30),eleven_cell_done TINYINT(1),eleven_cell_interpretation TEXT,performed_by INT UNSIGNED,performed_date DATE,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(center_id) REFERENCES blood_centers(id),FOREIGN KEY(performed_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE alloantibodies(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL,antibody VARCHAR(30) NOT NULL,`system` VARCHAR(20),clinical_significance ENUM('High','Moderate','Low','Unknown') DEFAULT 'High',titer VARCHAR(30),detected_at_center INT UNSIGNED,detected_date DATE,how_found VARCHAR(100),recorded_by INT UNSIGNED,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(detected_at_center) REFERENCES blood_centers(id),FOREIGN KEY(recorded_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE camps(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,camp_code VARCHAR(10) NOT NULL,camp_name VARCHAR(120) NOT NULL,camp_date DATE NOT NULL,location VARCHAR(200),units_collected INT UNSIGNED DEFAULT 0,notes TEXT,organized_by INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_camp_code_center(camp_code,center_id),FOREIGN KEY(center_id) REFERENCES blood_centers(id),FOREIGN KEY(organized_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE visits(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,hid VARCHAR(30),patient_id VARCHAR(15) NOT NULL,center_id INT UNSIGNED NOT NULL,visit_date DATE NOT NULL,weight_kg DECIMAL(5,2),target_hb DECIMAL(4,1),pre_hb DECIMAL(4,1),post_hb DECIMAL(4,1),units_calculated TINYINT UNSIGNED,units_given TINYINT UNSIGNED,product VARCHAR(30),next_due DATE,reaction ENUM('None','Mild','Moderate','Severe') DEFAULT 'None',reaction_notes TEXT,recorded_by INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_visit_hid(hid),INDEX idx_visit_patient(patient_id),INDEX idx_visit_center(center_id),INDEX idx_visit_due(next_due),FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(center_id) REFERENCES blood_centers(id),FOREIGN KEY(recorded_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bags(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bag_number VARCHAR(30) NOT NULL,center_id INT UNSIGNED NOT NULL,year SMALLINT UNSIGNED NOT NULL,donation_type ENUM('voluntary','replacement') NOT NULL DEFAULT 'voluntary',camp_id INT UNSIGNED,blood_group VARCHAR(4) NOT NULL,antigen_C TINYINT(1),antigen_c_lower TINYINT(1),antigen_E TINYINT(1),antigen_e_lower TINYINT(1),antigen_K TINYINT(1),antigen_Jka TINYINT(1),antigen_Jkb TINYINT(1),antigen_Fya TINYINT(1),antigen_Fyb TINYINT(1),phenotype_string VARCHAR(100),product ENUM('PRC','Whole Blood','FFP','Cryoprecipitate','Platelet','Other') NOT NULL DEFAULT 'PRC',volume_ml SMALLINT UNSIGNED,collection_date DATE NOT NULL,expiry_date DATE NOT NULL,status ENUM('available','issued','expired','discarded','quarantine') NOT NULL DEFAULT 'available',issued_to_visit INT UNSIGNED,issued_date DATE,notes TEXT,received_by INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bag_center_year(bag_number,center_id,year),INDEX idx_bag_lookup(center_id,status,blood_group,expiry_date),FOREIGN KEY(center_id) REFERENCES blood_centers(id),FOREIGN KEY(camp_id) REFERENCES camps(id),FOREIGN KEY(issued_to_visit) REFERENCES visits(id),FOREIGN KEY(received_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crossmatches(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,visit_id INT UNSIGNED NOT NULL,bag_id INT UNSIGNED NOT NULL,technique ENUM('IS','AHG','Enzyme','Electronic') NOT NULL,result ENUM('Compatible','Incompatible','Least Incompatible') NOT NULL,consent_taken TINYINT(1) NOT NULL DEFAULT 0,authorized_by VARCHAR(120),clinical_justification TEXT,antigen_override VARCHAR(255),performed_by INT UNSIGNED,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(bag_id) REFERENCES bags(id),FOREIGN KEY(performed_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ferritin_logs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL,test_date DATE NOT NULL,ferritin_ng_ml DECIMAL(10,2) NOT NULL,chelation_agent VARCHAR(100),chelation_dose VARCHAR(100),recorded_by INT UNSIGNED,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(recorded_by) REFERENCES staff(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE iron_assessments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(15) NOT NULL,test_date DATE,liver_T2star DECIMAL(7,2),cardiac_T2star DECIMAL(7,2),LIC DECIMAL(7,2),transferrin_sat DECIMAL(6,2),ALT DECIMAL(7,2),AST DECIMAL(7,2),FOREIGN KEY(patient_id) REFERENCES patients(patient_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bag_sequences(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,year SMALLINT UNSIGNED NOT NULL,last_seq INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_center_year(center_id,year),FOREIGN KEY(center_id) REFERENCES blood_centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_type ENUM('staff','patient') NOT NULL,actor_id INT UNSIGNED,action VARCHAR(80) NOT NULL,target_table VARCHAR(80) NOT NULL,target_id VARCHAR(80),field VARCHAR(80),before_value TEXT,after_value TEXT,center_id INT UNSIGNED,ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_target(target_table,target_id),FOREIGN KEY(center_id) REFERENCES blood_centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE portal_login_attempts(throttle_key CHAR(64) NOT NULL PRIMARY KEY,failure_count TINYINT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME NULL,last_attempt_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_portal_login_locked(locked_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
